module radix2_div(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, output res_valid, output [15:0] result
);
// TODO: Please add your solution here
reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [8:0] neg_divisor;
reg start_cnt;
reg [3:0] cnt;
reg res_valid_reg;
reg [15:0] result_reg;
reg sr_carry_out;
wire [9:0] sub_result;
wire [8:0] mux_out;
wire [8:0] sr_in;
assign sub_result[9] = SR[8];
assign sub_result[8:0] = SR[7:0] + neg_divisor;
assign mux_out[7:0] = sr_carry_out ? sub_result[8:1] : sub_result[8:1] + 9'd1;
assign sr_in = mux_out;
assign result = result_reg;
assign res_valid = res_valid_reg;
always @(*) begin
    case(cnt)
        4'd0: sr_carry_out = ~sub_result[9];
        default: sr_carry_out = sub_result[9];
    endcase
end
always @(posedge clk or posedge rst) begin
    if(rst) begin
        cnt <= 4'd0;
        start_cnt <= 1'b0;
        res_valid_reg <= 1'b0;
        result_reg <= 16'd0;
    end else begin
        if(opn_valid && !res_valid_reg) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            neg_divisor <= {~|divisor, ~divisor}+1'b1;
            SR <= {dividend, 1'b0};
            cnt <= 4'd1;
            start_cnt <= 1'b1;
        end else if(start_cnt) begin
            if(&cnt) begin
                cnt <= 4'd0;
                start_cnt <= 1'b0;
                res_valid_reg <= 1'b1;
                result_reg <= {SR[8], SR[7:0]};
            end else begin
                cnt <= cnt + 1'b1;
                SR <= sr_in;
            end
        end else begin
            res_valid_reg <= 1'b0;
        end
    end
end
reg [15:0] SR;
endmodule
